<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{NButton,NForm,NFormItem,NInput,NInputNumber,NModal,NSelect,NSwitch,NTag,useMessage}from'naive-ui';import{api}from'../api';const rows=ref<any[]>([]),show=ref(false),message=useMessage(),driver=ref<'local'|'s3'>('local'),base=reactive<any>({name:'本地存储',is_default:false,is_enabled:true,remark:''}),local=reactive({root:'files'}),s3=reactive<any>({endpoint:'',region:'auto',bucket:'',access_key_id:'',secret_access_key:'',base_path:'files/',force_path_style:false,public_base_url:'',presign_expire_minutes:30});async function load(){rows.value=await api.get('/storages') as any[]}function open(){driver.value='local';Object.assign(base,{name:'本地存储',is_default:false,is_enabled:true,remark:''});show.value=true}async function save(){try{await api.post('/storages',{...base,driver:driver.value,config:JSON.stringify(driver.value==='local'?local:s3)});show.value=false;message.success('存储已保存');load()}catch(e:any){message.error(e.message)}}async function test(id:number){try{const x:any=await api.post(`/storages/${id}/test`);message.success(`连接正常，${x.latency_ms} ms`)}catch(e:any){message.error(e.message)}}onMounted(load)</script>
<template><div class="page-head"><div><h1>存储管理</h1><span style="color:#8b93a1">支持本地磁盘与 S3 兼容服务，密钥加密保存且不回显</span></div><n-button type="primary" @click="open">添加存储</n-button></div><div class="metric-grid"><div v-for="s in rows" :key="s.id" class="metric"><div><n-tag>{{s.driver}}</n-tag> <n-tag v-if="s.is_default" type="success">默认</n-tag></div><strong style="font-size:21px">{{s.name}}</strong><span>{{s.remark||s.config}}</span><div style="margin-top:16px"><n-button size="small" @click="test(s.id)">测试连接</n-button></div></div></div><n-modal v-model:show="show" preset="card" title="添加存储" style="max-width:680px"><n-form label-placement="top"><div class="form-grid"><n-form-item label="驱动"><n-select v-model:value="driver" :options="[{label:'本地磁盘',value:'local'},{label:'S3 兼容对象存储',value:'s3'}]"/></n-form-item><n-form-item label="名称"><n-input v-model:value="base.name"/></n-form-item><template v-if="driver==='local'"><n-form-item class="wide" label="数据目录下的相对路径或绝对路径"><n-input v-model:value="local.root"/></n-form-item></template><template v-else><n-form-item class="wide" label="Endpoint"><n-input v-model:value="s3.endpoint" placeholder="https://<account>.r2.cloudflarestorage.com"/></n-form-item><n-form-item label="Region"><n-input v-model:value="s3.region"/></n-form-item><n-form-item label="Bucket"><n-input v-model:value="s3.bucket"/></n-form-item><n-form-item label="Access Key ID"><n-input v-model:value="s3.access_key_id"/></n-form-item><n-form-item label="Secret Access Key"><n-input v-model:value="s3.secret_access_key" type="password"/></n-form-item><n-form-item label="桶内前缀"><n-input v-model:value="s3.base_path"/></n-form-item><n-form-item label="公共下载域名"><n-input v-model:value="s3.public_base_url" placeholder="https://dl.example.com"/></n-form-item><n-form-item label="预签名有效分钟"><n-input-number v-model:value="s3.presign_expire_minutes"/></n-form-item><n-form-item label="Path-style"><n-switch v-model:value="s3.force_path_style"/></n-form-item></template><n-form-item label="备注"><n-input v-model:value="base.remark"/></n-form-item><n-form-item label="设为默认"><n-switch v-model:value="base.is_default"/></n-form-item></div><n-button type="primary" @click="save">保存</n-button></n-form></n-modal></template>

